# Core logic for reading CSV, parsing amounts with Decimal, handling categories (blank->uncategorized), and returning structured totals.

```python
from decimal import Decimal, InvalidOperation
from pathlib import Path
from typing import Any


def read_totals(path: str) -> dict[str, Any]:
    """
    Read expense CSV and return total amount and breakdown by category.

    Args:
        path: Path to CSV file with columns 'category' and 'amount'.

    Returns:
        Dictionary with 'total' (string, two decimals) and 'by_category' (dict of strings).

    Raises:
        ValueError: If amount is invalid or required columns are missing.
    """
    path_obj = Path(path)
    if not path_obj.exists():
        raise ValueError(f"File not found: {path}")

    total = Decimal("0")
    by_category: dict[str, Decimal] = {}

    with open(path_obj, "r", encoding="utf-8") as f:
        lines = f.readlines()

    if len(lines) < 2:
        return {"total": "0.00", "by_category": {}}

    header_line = lines[0].strip()
    columns = [col.strip() for col in header_line.split(",")]

    if "category" not in columns or "amount" not in columns:
        raise ValueError(f"Missing required columns 'category' and 'amount'. Found: {columns}")

    category_idx = columns.index("category")
    amount_idx = columns.index("amount")

    for row_num, line in enumerate(lines[1:], start=2):
        if not line.strip():
            continue

        values = [v.strip() for v in line.split(",")]

        if len(values) <= max(category_idx, amount_idx):
            raise ValueError(f"Invalid row {row_num}: insufficient columns")

        category_str = values[category_idx]
        amount_str = values[amount_idx]

        try:
            amount = Decimal(amount_str)
        except (InvalidOperation, ValueError) as e:
            raise ValueError(f"Invalid amount in row {row_num}: {e}")

        if category_str == "":
            category = "uncategorized"
        else:
            category = category_str

        total += amount
        by_category[category] = by_category.get(category, Decimal("0")) + amount

    return {
        "total": str(total.quantize(Decimal("0.01"))),
        "by_category": {k: str(v.quantize(Decimal("0.01"))) for k, v in by_category.items()}
    }
